<script setup lang="ts">import {computed} from 'vue';import {ComparisonResult} from '../types/comparison';import {number} from '../utils/format';import DataTable from './common/DataTable.vue';const props=defineProps<{result:ComparisonResult}>();const sorted=computed(()=>[...props.result.ratios].sort((a,b)=>a.delta-b.delta));const width=(v:number)=>Math.min(100,Math.max(2,(v/(props.result.summary.R2_max||1))*100));</script><template><section class="sensitivity-panel"><div class="section-top"><h3>同一冻结样本下的零替换敏感性</h3><span>样本、组别、组规模与置换序列固定，仅改变δ</span></div><div class="frozen-strip"><span><b>{{result.frozen.sample_count}}</b> 冻结样本</span><span><b>{{result.frozen.zero_rows}}</b> 行含零</span><span v-for="(n,g) in result.frozen.group_counts" :key="g"><b>{{n}}</b> {{g}}</span><span><b>{{result.permutations}}</b> 次置换 / seed {{result.seed}}</span></div><div class="sensitivity-rows"><div v-for="r in sorted" :key="r.delta" :class="['sensitivity-row','ratio-'+r.F_status]"><div class="ratio-delta"><b>δ={{r.delta}}</b><small>{{r.zero_rows}}行含零</small></div><div class="ratio-bar"><span :style="{width:width(r.R2)+'%'}"/></div><div class="ratio-stat"><b>{{number(r.R2,4)}}</b><small>R²</small></div><div class="ratio-stat"><b>{{number(r.p,4)}}</b><small>p / {{result.permutations}}次</small></div><div :class="['ratio-conclusion',r.p<result.summary.alpha?'reject':'retain']">{{r.p<result.summary.alpha?'拒绝无组差':'未拒绝无组差'}}</div></div></div><div :class="['sensitivity-verdict',result.summary.changed?'changed':'stable']"><b>{{result.summary.changed?'结论随δ改变':'结论在所选δ内保持'}}</b><p v-if="result.summary.changed"><span v-for="(c,i) in result.summary.changes" :key="i">δ {{c.from}} → {{c.to}}：{{c.from_conclusion}} → {{c.to_conclusion}}</span></p><p v-else>所选{{result.ratios.length}}个比例在0.05水平下得到相同结论；这不等于结论稳健，仍需保留δ假设与置换波动。</p><small>固定置换序列 {{result.permutation.schedule_hash.slice(0,16)}} · 标签 {{result.permutation.labels_hash.slice(0,16)}} · 批注 {{result.frozen.annotations_hash.slice(0,16)}}</small></div><div class="section-heading"><h2>逐比例全局证据</h2><span>每个δ独立变换、同一标签序列置换</span></div><DataTable :head="['δ','零行','R²','pseudo-F','p','上尾极端','结论']"><tr v-for="r in sorted" :key="r.delta"><td>{{r.delta}}</td><td>{{r.zero_rows}}</td><td>{{number(r.R2,5)}}</td><td>{{r.F_status==='unbounded'?'无界':r.F_status==='numerical_overflow'?'数值超范围':number(r.F,5)}}</td><td>{{number(r.p,4)}}</td><td>{{r.extreme}} / {{result.permutations}}</td><td>{{r.conclusion}}</td></tr></DataTable><p class="sensitivity-note">{{result.assumptions}}</p><p class="sensitivity-note">{{result.interpretation}}</p><p class="fingerprint">{{result.algorithm_version}} / SENSITIVITY SHA256 {{result.input_hash}}</p></section></template>
